      int right = nums.length - 1;
      while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                  return mid;
            }
            if (nums[left] <= nums[mid]) {
                  if (target < nums[mid] && target >= nums[left]) {
                        right = mid - 1;
                  } else {
                        left = mid + 1;
