private static boolean isCenterSymmetric(String num) {
    int mid = num.length() / 2;
    for (int i = 0; i < mid; i++) {
        if (num.charAt(mid + i) != num.charAt(num.length() - mid - i - 1)) {
            return false;
        }
    }
    return true;
}
